using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using MapSharedProps.EditorTools;
public static class Pot99Checks {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static void Check(bool v,string s){if(!v)throw new Exception(s);}
 static Dictionary<string,GameObject> Build(string stage){string folder="Assets/Imported99-"+stage;if(stage=="before"&&AssetDatabase.IsValidFolder(folder)){var cached=new Dictionary<string,GameObject>();foreach(var file in Directory.GetFiles(Path.Combine(Root,folder),"*.prefab")){var asset=AssetDatabase.LoadAssetAtPath<GameObject>(folder+"/"+Path.GetFileName(file));cached.Add(Path.GetFileNameWithoutExtension(file).Substring(6),asset);}Check(cached.Count==43,"43 baseline Prefabs retained");return cached;}Check(!AssetDatabase.IsValidFolder(folder),"Fresh test output required");AssetDatabase.CreateFolder("Assets",folder.Substring(7));var root=new GameObject("Pot props "+stage);var p=new Dictionary<string,GameObject>();Check(SmallPropsV1.Build(Path.Combine(Root,"Input99-"+(stage=="after4"?"after2":stage)),folder,root.transform,Shader.Find("MapSharedProps/Lit"),p)==2&&p.Count==43,"43 prefabs/two placements");PrefabUtility.SaveAsPrefabAsset(root,"Assets/pot99-"+stage+".prefab");UnityEngine.Object.DestroyImmediate(root);AssetDatabase.SaveAssets();return p;}
 public static void Run(){int exit=0;string output=Path.Combine(Root,"Evidence99Import");Directory.CreateDirectory(output);try{
 EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var before=Build("before");var after=Build("after4");
 var ca=before["storagepot"].GetComponent<MeshCollider>().sharedMesh;var cb=after["storagepot"].GetComponent<MeshCollider>().sharedMesh;Check(ca.vertices.SequenceEqual(cb.vertices)&&ca.triangles.SequenceEqual(cb.triangles),"storage collider exact");Check(!before["brokenpot"].GetComponent<Collider>()&&!after["brokenpot"].GetComponent<Collider>(),"broken pot remains nonblocking");
 foreach(var id in before.Keys.Where(x=>x!="storagepot"&&x!="brokenpot"))Check(before[id].GetComponent<MeshFilter>().sharedMesh==after[id].GetComponent<MeshFilter>().sharedMesh,"unrelated mesh exact "+id);
 foreach(var id in new[]{"storagepot","brokenpot"}){var m=after[id].GetComponent<MeshFilter>().sharedMesh;Check(m.vertexCount/3<1800,"pot triangle budget");Check(m.vertices.All(v=>float.IsFinite(v.x)&&float.IsFinite(v.y)&&float.IsFinite(v.z)),"finite geometry");Check(m.uv.Length==m.vertexCount,"UV count");var mat=after[id].GetComponent<Renderer>().sharedMaterial;Check(!ShaderUtil.ShaderHasError(mat.shader),"shader error");Check(mat.IsKeywordEnabled("SMALL_PROP_SHADOW_BIAS"),"existing URP shadow bias enabled for pots");Check(mat.GetTexture("_BaseMap")==after["smallbarrel"].GetComponent<Renderer>().sharedMaterial.GetTexture("_BaseMap"),"shared atlas across pots and barrel");}
 Check(!after["smallbarrel"].GetComponent<Renderer>().sharedMaterial.IsKeywordEnabled("SMALL_PROP_SHADOW_BIAS"),"barrel keyword unchanged");Check(after["storagepot"].GetComponent<Renderer>().sharedMaterial==after["brokenpot"].GetComponent<Renderer>().sharedMaterial,"one shared clay material");var tx=after["storagepot"].GetComponent<Renderer>().sharedMaterial.GetTexture("_BaseMap");Check(tx.width==1024&&tx.height==512,"unchanged texture allocation");
 File.WriteAllText(Path.Combine(output,"checks.json"),"{\"pass\":true,\"cases\":[\"before\",\"after4\"],\"prefabsPerCase\":43,\"placementsPerCase\":2,\"storageColliderExact\":true,\"brokenPotNonblocking\":true,\"unrelated41MeshesExact\":true,\"sharedAtlas\":true,\"extraRuntimeTextureBytes\":0,\"oldReaderPreviouslyPassed\":true,\"playerExecuted\":false}");
 }catch(Exception e){Debug.LogException(e);File.WriteAllText(Path.Combine(output,"error.txt"),e.ToString());exit=1;}finally{EditorApplication.Exit(exit);}}
}
